def select_next_node(graph, unvisited_nodes):
    candidate_sets = {
        n: set(graph.neighbors(n)) & set(unvisited_nodes)
        if len(set(graph.neighbors(n)) & set(unvisited_nodes)) > 0
        else {n} for n in unvisited_nodes
    }
    filtered_candidates = {n: neighbors for n, neighbors in candidate_sets.items() if neighbors != {n}}
    if filtered_candidates:
        # Pick the node with the largest number of unvisited neighbors
        max_neighbors = max(len(neigh) for neigh in filtered_candidates.values())
        candidates_max_neigh = [n for n, neigh in filtered_candidates.items() if len(neigh) == max_neighbors]
        # Break ties by highest clustering coefficient
        next_node = max(candidates_max_neigh, key=lambda n: graph.nodes[n]['clustering'])
        return next_node
    else:
        # If no node has unvisited neighbors, select node maximizing core_number * eigenvector
        score_func = lambda n: graph.nodes[n]['core_number'] * graph.nodes[n]['eigenvector']
        next_node = max(unvisited_nodes, key=score_func)
        return next_node
